import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]

    # For each X and lower endpoint l, store the minimum R among
    # constraints with that X and L >= l. Such a constraint is active
    # inside [l, r] exactly when this minimum is at most r.
    inf = n + 1
    min_r = [[inf] * (n + 2) for _ in range(n + 1)]
    pos = 2
    for _ in range(m):
        left, right, x = data[pos], data[pos + 1], data[pos + 2]
        pos += 3
        if right < min_r[x][left]:
            min_r[x][left] = right

    for x in range(1, n + 1):
        for left in range(n - 1, 0, -1):
            if min_r[x][left + 1] < min_r[x][left]:
                min_r[x][left] = min_r[x][left + 1]

    choose = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        choose[i][0] = choose[i][i] = 1
        for j in range(1, i):
            choose[i][j] = (choose[i - 1][j - 1] + choose[i - 1][j]) % MOD

    # Empty intervals have one ordering.
    dp = [[0] * (n + 2) for _ in range(n + 2)]
    for i in range(1, n + 2):
        dp[i][i - 1] = 1

    for length in range(1, n + 1):
        for left in range(1, n - length + 2):
            right = left + length - 1
            total = 0
            for root in range(left, right + 1):
                # If an active condition names the interval maximum, it fails.
                if min_r[root][left] <= right:
                    continue
                ways = dp[left][root - 1] * dp[root + 1][right] % MOD
                ways = ways * choose[length - 1][root - left] % MOD
                total += ways
            dp[left][right] = total % MOD

    print(dp[1][n])

if __name__ == '__main__':
    main()

