import sys

MOD = 998244353

def factorize(x):
    result = []
    d = 2
    while d * d <= x:
        if x % d == 0:
            e = 0
            while x % d == 0:
                x //= d
                e += 1
            result.append((d, e))
        d += 1
    if x > 1:
        result.append((x, 1))
    return result

def contribution(p, exponents):
    dp = {0: 1}
    for i, e in enumerate(exponents, 1):
        ndp = {}
        deltas = (0,) if e == 0 else (-e, e)
        for h, value in dp.items():
            for delta in deltas:
                z = h + delta
                if z >= 0:
                    nh = z
                    mul = pow(p, nh, MOD)
                else:
                    nh = 0
                    mul = pow(p, i * (-z), MOD)
                ndp[nh] = (ndp.get(nh, 0) + value * mul) % MOD
        dp = ndp
    return sum(dp.values()) % MOD

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    a = data[1:]
    primes = set()
    for x in a:
        primes.update(p for p, _ in factorize(x))
    answer = 1
    for p in primes:
        exponents = []
        for x in a:
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            exponents.append(e)
        answer = answer * contribution(p, exponents) % MOD
    print(answer)

if __name__ == '__main__':
    main()

