import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    values = data[1:1 + n]
    limit = max(values)

    # proper_divisors[x] contains every possible destination from x
    proper_divisors = [[] for _ in range(limit + 1)]
    for d in range(1, limit // 2 + 1):
        for x in range(2 * d, limit + 1, d):
            proper_divisors[x].append(d)

    # Sprague-Grundy value: mex of the values reachable by one move.
    grundy = [0] * (limit + 1)
    for x in range(2, limit + 1):
        reachable = {grundy[d] for d in proper_divisors[x]}
        g = 0
        while g in reachable:
            g += 1
        grundy[x] = g

    nim_sum = 0
    for x in values:
        nim_sum ^= grundy[x]
    print('Anna' if nim_sum else 'Bruno')

if __name__ == '__main__':
    main()

