from typing import List
import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        # Activate each constraint when its larger endpoint is reached.
        starts = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            starts[b].append((a, i))

        active = []  # max-heap of (negative smaller endpoint, pair id)
        gain = [0] * len(conflictingPairs)
        base = 0

        for right in range(1, n + 1):
            for left, pair_id in starts[right]:
                heapq.heappush(active, (-left, pair_id))

            if not active:
                base += right
                continue

            # The largest active left endpoint determines valid starts.
            neg_left, pair_id = heapq.heappop(active)
            largest = -neg_left
            second_largest = -active[0][0] if active else 0

            base += right - largest
            # Removing this pair helps only when it is the unique maximum.
            if second_largest < largest:
                gain[pair_id] += largest - second_largest

            heapq.heappush(active, (neg_left, pair_id))

        return base + max(gain)

