import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    n = next(it)
    m = next(it)
    q = next(it)

    edges = [None] * m
    for k in range(m):
        a = next(it) - 1
        b = next(it) - 1
        c = next(it)
        edges[k] = (a, b, c)

    queries = []
    deleted = set()
    for _ in range(q):
        t = next(it)
        if t == 1:
            e = next(it) - 1
            queries.append((1, e))
            deleted.add(e)
        else:
            x = next(it) - 1
            y = next(it) - 1
            queries.append((2, x, y))

    inf = 10**30
    dist = [[inf] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for e, (a, b, c) in enumerate(edges):
        if e not in deleted:
            dist[a][b] = dist[b][a] = c

    # APSP in the graph after all closures.
    for k in range(n):
        dk = dist[k]
        for i in range(n):
            dik = dist[i][k]
            if dik == inf:
                continue
            di = dist[i]
            for j in range(n):
                candidate = dik + dk[j]
                if candidate < di[j]:
                    di[j] = candidate

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            value = dist[query[1]][query[2]]
            answers.append(-1 if value == inf else value)
        else:
            a, b, c = edges[query[1]]
            da = dist[a]
            db = dist[b]
            # Distances are symmetric; update only one triangle and mirror it.
            for i in range(n):
                di = dist[i]
                ia = di[a]
                ib = di[b]
                for j in range(i, n):
                    candidate1 = ia + c + db[j]
                    candidate2 = ib + c + da[j]
                    if candidate2 < candidate1:
                        candidate1 = candidate2
                    if candidate1 < di[j]:
                        di[j] = candidate1
                        dist[j][i] = candidate1

    sys.stdout.write('\n'.join(map(str, reversed(answers))))

if __name__ == '__main__':
    main()

