from math import gcd

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, budget = data[0], data[1]
    items = []
    idx = 2
    max_rate = 0
    for _ in range(n):
        a, p, b, q = data[idx:idx + 4]
        idx += 4
        max_rate = max(max_rate, a, b)
        g = gcd(a, b)
        if p * b <= q * a:
            # S has no greater cost per unit of capacity. An optimum
            # needs fewer than a/g copies of T.
            items.append((a, p, b, q, 0, a // g))
        else:
            # T is cheaper per unit; enumerate fewer than b/g copies of S.
            items.append((a, p, b, q, 1, b // g))

    def feasible(target):
        total = 0
        for a, p, b, q, mode, limit in items:
            best = 10**30
            if mode == 0:
                for y in range(limit):
                    rem = target - b * y
                    x = 0 if rem <= 0 else (rem + a - 1) // a
                    cost = x * p + y * q
                    if cost < best:
                        best = cost
            else:
                for x in range(limit):
                    rem = target - a * x
                    y = 0 if rem <= 0 else (rem + b - 1) // b
                    cost = x * p + y * q
                    if cost < best:
                        best = cost
            total += best
            if total > budget:
                return False
        return True

    lo, hi = 0, budget * max_rate + 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid
    print(lo)

