class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Binomial coefficients modulo MOD, up to n.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # Count values strictly less than s, grouped by their number of 1 bits.
        counts = [0] * (n + 1)
        ones_so_far = 0
        for i, ch in enumerate(s):
            if ch == '1':
                remaining = n - i - 1
                # At this position choose 0; prior bits are fixed, and the
                # remaining suffix supplies the required number of 1 bits.
                for total_ones in range(ones_so_far, n + 1):
                    need = total_ones - ones_so_far
                    if need <= remaining:
                        counts[total_ones] = (
                            counts[total_ones] + comb[remaining][need]
                        ) % MOD
                ones_so_far += 1

        answer = 0
        for total_ones in range(1, n + 1):
            # For x > 1, the first operation gives total_ones; thus x is
            # k-reducible exactly when total_ones reaches 1 in <= k-1 steps.
            value = total_ones
            steps = 0
            while value > 1:
                value = value.bit_count()
                steps += 1
            if steps <= k - 1:
                answer = (answer + counts[total_ones]) % MOD

        return answer

