import sys
from collections import deque

def solve():
    input=sys.stdin.readline
    n=int(input())
    g=[input().strip() for _ in range(n)]
    dist=[[-1]*n for _ in range(n)]
    q=deque()
    for i in range(n):
        dist[i][i]=0; q.append((i,i))
    for i in range(n):
        for j in range(n):
            if g[i][j]!='-' and dist[i][j]<0:
                dist[i][j]=1; q.append((i,j))
    incoming=[[0]*26 for _ in range(n)]
    outgoing=[[0]*26 for _ in range(n)]
    for a in range(n):
        for b,ch in enumerate(g[a]):
            if ch!='-':
                c=ord(ch)-97
                outgoing[a][c] |= 1<<b
                incoming[b][c] |= 1<<a
    while q:
        i,j=q.popleft()
        nd=dist[i][j]+2
        # a -> i and j -> b with matching labels
        for c in range(26):
            amask=incoming[i][c]
            bmask=outgoing[j][c]
            while amask:
                abit=amask & -amask; amask-=abit
                a=abit.bit_length()-1
                new=bmask
                while new:
                    bit=new & -new; new-=bit
                    b=bit.bit_length()-1
                    if dist[a][b]<0:
                        dist[a][b]=nd
                        q.append((a,b))
    print('\n'.join(' '.join(map(str,row)) for row in dist))

if __name__=='__main__': solve()

