import math

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odd_count = (n + 1) // 2
        even_count = n // 2
        total = math.factorial(odd_count) * math.factorial(even_count)
        if n % 2 == 0:
            total *= 2
        if k > total:
            return []

        remaining = set(range(1, n + 1))
        answer = []
        previous = None

        for _ in range(n):
            chosen = None
            for x in sorted(remaining):
                if previous is not None and x % 2 == previous % 2:
                    continue

                left = len(remaining) - 1
                remaining_odds = sum(y % 2 for y in remaining if y != x)
                remaining_evens = left - remaining_odds

                if left == 0:
                    completions = 1
                else:
                    first_parity = 1 - (x % 2)
                    first_slots = (left + 1) // 2
                    other_slots = left // 2
                    odd_slots = first_slots if first_parity == 1 else other_slots
                    even_slots = first_slots if first_parity == 0 else other_slots
                    if (remaining_odds, remaining_evens) == (odd_slots, even_slots):
                        completions = math.factorial(remaining_odds) * math.factorial(remaining_evens)
                    else:
                        completions = 0

                if k > completions:
                    k -= completions
                else:
                    chosen = x
                    break

            if chosen is None:
                return []
            answer.append(chosen)
            remaining.remove(chosen)
            previous = chosen

        return answer

