class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        coeff = []
        for i in range(h):
            a = pow(10, i, k)
            b = pow(10, n - 1 - i, k)
            coeff.append(a if i == n - 1 - i else (a + b) % k)

        # reachable[i, r] indicates whether variables i..h-1 can
        # contribute residue r modulo k.
        reach = bytearray((h + 1) * k)
        reach[h * k] = 1
        for i in range(h - 1, -1, -1):
            cur = i * k
            nxt = (i + 1) * k
            c = coeff[i]
            for r in range(k):
                for d in range(10):
                    if reach[nxt + (r - c * d) % k]:
                        reach[cur + r] = 1
                        break

        prefix = []
        residue = 0
        for i, c in enumerate(coeff):
            low = 1 if i == 0 else 0
            for d in range(9, low - 1, -1):
                need = (-residue - c * d) % k
                if reach[(i + 1) * k + need]:
                    prefix.append(str(d))
                    residue = (residue + c * d) % k
                    break

        left = ''.join(prefix)
        return left + (left[:-1][::-1] if n % 2 else left[::-1])

