from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nxt = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            nxt[i] = stack[-1] if stack else n
            stack.append(i)

        prefix = [0] * (n + 1)
        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x

        levels = n.bit_length()
        jumps = [nxt]
        costs = [[nums[i] * (nxt[i] - i) - (prefix[nxt[i]] - prefix[i])
                  for i in range(n)]]
        for _ in range(1, levels):
            prev_jump = jumps[-1]
            prev_cost = costs[-1]
            cur_jump = [n] * n
            cur_cost = [0] * n
            for i in range(n):
                mid = prev_jump[i]
                cur_cost[i] = prev_cost[i] + (prev_cost[mid] if mid < n else 0)
                cur_jump[i] = prev_jump[mid] if mid < n else n
            jumps.append(cur_jump)
            costs.append(cur_cost)

        def required(l, r):
            total = 0
            p = l
            for b in range(levels - 1, -1, -1):
                q = jumps[b][p]
                if q <= r:
                    total += costs[b][p]
                    p = q
            return total + nums[p] * (r - p + 1) - (prefix[r + 1] - prefix[p])

        answer = 0
        for l in range(n):
            lo, hi = l - 1, n
            while hi - lo > 1:
                mid = (lo + hi) // 2
                if required(l, mid) <= k:
                    lo = mid
                else:
                    hi = mid
            answer += lo - l + 1
        return answer

