class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        parent[0] = 0
        order = [0]
        for u in order:
            for v, _ in graph[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        dp0 = [0] * n  # parent edge absent: up to k child edges
        dp1 = [0] * n  # parent edge present: up to k-1 child edges
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if parent[v] == u:
                    base += dp0[v]
                    gains.append(w + dp1[v] - dp0[v])
            gains.sort(reverse=True)
            dp0[u] = base + sum(x for x in gains[:k] if x > 0)
            dp1[u] = base + sum(x for x in gains[:max(0, k - 1)] if x > 0)
        return dp0[0]

