import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N, M, L = data[:3]
    values = data[3:]
    cards = values[:N + M + L]
    full = (1 << len(cards)) - 1

    takahashi = (1 << N) - 1
    aoki = ((1 << M) - 1) << N

    @lru_cache(None)
    def winning(t, a, turn):
        hand = t if turn == 0 else a
        if hand == 0:
            return False

        table = full ^ t ^ a
        bits = hand
        while bits:
            played = bits & -bits
            bits -= played
            value = cards[played.bit_length() - 1]

            if turn == 0:
                next_t, next_a = t ^ played, a
            else:
                next_t, next_a = t, a ^ played

            # Play without taking a card.
            if not winning(next_t, next_a, 1 - turn):
                return True

            # Or take any lower-valued card that was already on the table.
            candidates = table
            while candidates:
                taken = candidates & -candidates
                candidates -= taken
                if cards[taken.bit_length() - 1] < value:
                    if turn == 0:
                        result = winning(next_t | taken, next_a, 1 - turn)
                    else:
                        result = winning(next_t, next_a | taken, 1 - turn)
                    if not result:
                        return True

        return False

    print("Takahashi" if winning(takahashi, aoki, 0) else "Aoki")

