from bisect import bisect_left, bisect_right

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, b, c = p.split('*')

        def occurrences(t):
            if not t:
                return list(range(n + 1))

            lps = [0] * len(t)
            j = 0
            for i in range(1, len(t)):
                while j and t[i] != t[j]:
                    j = lps[j - 1]
                if t[i] == t[j]:
                    j += 1
                lps[i] = j

            found = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = lps[j - 1]
                if ch == t[j]:
                    j += 1
                if j == len(t):
                    found.append(i - len(t) + 1)
                    j = lps[j - 1]
            return found

        starts_a = occurrences(a)
        starts_b = occurrences(b)
        starts_c = occurrences(c)
        answer = n + 1

        for start_b in starts_b:
            # The latest A ending before B gives the shortest possible prefix.
            ia = bisect_right(starts_a, start_b - len(a)) - 1
            if ia < 0:
                continue

            # The earliest C starting after B gives the shortest possible suffix.
            ic = bisect_left(starts_c, start_b + len(b))
            if ic == len(starts_c):
                continue

            start = starts_a[ia]
            end = starts_c[ic] + len(c)
            answer = min(answer, end - start)

        return -1 if answer == n + 1 else answer

