import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    adj = [[] for _ in range(n)]
    k = 2
    for _ in range(m):
        x, y, z = data[k] - 1, data[k + 1] - 1, data[k + 2]
        k += 3
        adj[x].append((y, z))
        adj[y].append((x, z))

    potential = [-1] * n
    answer = [0] * n
    for start in range(n):
        if potential[start] != -1:
            continue
        potential[start] = 0
        stack = [start]
        component = []
        consistent = True
        while stack:
            v = stack.pop()
            component.append(v)
            for u, z in adj[v]:
                required = potential[v] ^ z
                if potential[u] == -1:
                    potential[u] = required
                    stack.append(u)
                elif potential[u] != required:
                    consistent = False

        if not consistent:
            print(-1)
            return

        ones = [0] * 30
        for v in component:
            value = potential[v]
            for bit in range(30):
                ones[bit] += (value >> bit) & 1

        # Choose the component's free XOR offset independently per bit.
        offset = 0
        for bit, count in enumerate(ones):
            if 2 * count > len(component):
                offset |= 1 << bit
        for v in component:
            answer[v] = potential[v] ^ offset

    print(*answer)

if __name__ == '__main__':
    solve()

