from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Iterative postorder traversal; reversed pushes preserve increasing
        # child order when nodes are popped.
        postorder = []
        stack = [(0, False)]
        while stack:
            node, visited = stack.pop()
            if visited:
                postorder.append(node)
            else:
                stack.append((node, True))
                for child in reversed(children[node]):
                    stack.append((child, False))

        subtree_size = [1] * n
        for node in postorder:
            p = parent[node]
            if p != -1:
                subtree_size[p] += subtree_size[node]

        position = [0] * n
        chars = []
        for i, node in enumerate(postorder):
            position[node] = i
            chars.append(s[node])
        text = ''.join(chars)

        # Manacher radii: d1[i] includes the center; d2[i] is centered
        # between i-1 and i.
        d1 = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(d1[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and text[i - k] == text[i + k]:
                k += 1
            d1[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        d2 = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(d2[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i - k - 1] == text[i + k]:
                k += 1
            d2[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for node in range(n):
            end = position[node]
            length = subtree_size[node]
            start = end - length + 1
            if length % 2:
                center = (start + end) // 2
                answer[node] = d1[center] >= length // 2 + 1
            else:
                center = (start + end + 1) // 2
                answer[node] = d2[center] >= length // 2
        return answer

