class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0

        # Each index i contributes the line dp[i] + (x - i) * nums[i].
        tree = [None] * (4 * n)

        def evaluate(line, x):
            return line[0] * x + line[1]

        def add(node, left, right, line):
            current = tree[node]
            if current is None:
                tree[node] = line
                return

            mid = (left + right) // 2
            if evaluate(line, mid) > evaluate(current, mid):
                tree[node], line = line, current
                current = tree[node]

            if left == right:
                return
            if evaluate(line, left) > evaluate(current, left):
                add(node * 2, left, mid, line)
            elif evaluate(line, right) > evaluate(current, right):
                add(node * 2 + 1, mid + 1, right, line)

        def query(node, left, right, x):
            best = evaluate(tree[node], x) if tree[node] is not None else -1
            if left == right:
                return best
            mid = (left + right) // 2
            if x <= mid:
                return max(best, query(node * 2, left, mid, x))
            return max(best, query(node * 2 + 1, mid + 1, right, x))

        add(1, 0, n - 1, (nums[0], 0))
        score = 0
        for j in range(1, n):
            score = query(1, 0, n - 1, j)
            add(1, 0, n - 1, (nums[j], score - j * nums[j]))
        return score

