from collections import Counter

class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        counts = Counter(nums)
        total = sum(nums)

        for outlier in sorted(counts, reverse=True):
            remaining = total - outlier
            if remaining % 2 != 0:
                continue
            sum_value = remaining // 2
            needed = 2 if sum_value == outlier else 1
            if counts.get(sum_value, 0) >= needed:
                return outlier

        # The input guarantees that a potential outlier exists.
        return 0

