class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        limit = 10 ** len(str(n))
        prime = bytearray(b'\x01') * limit
        prime[0] = 0
        if limit > 1:
            prime[1] = 0
        for i in range(2, int(limit ** 0.5) + 1):
            if prime[i]:
                start = i * i
                count = (limit - 1 - start) // i + 1
                prime[start:limit:i] = b'\x00' * count

        if prime[n] or prime[m]:
            return -1

        places = [10 ** i for i in range(len(str(n)))]
        dist = [float('inf')] * limit
        dist[n] = n  # The starting value is included in the total cost.
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            for place in places:
                digit = (value // place) % 10
                if digit > 0:
                    nxt = value - place
                    if not prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (dist[nxt], nxt))
                if digit < 9:
                    nxt = value + place
                    if not prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (dist[nxt], nxt))

        return -1

