from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        answer = 0
        # next_row[j] is LCP(nums[i+1:], nums[j:]) while processing i.
        next_row = [0] * (n + 1)

        for i in range(n - 2, 0, -1):
            current = [0] * (n + 1)

            # nums[0:i] is a prefix of nums[i:j] exactly when this holds
            # and j >= 2*i. Such valid j are 2*i .. n-1.
            first_is_prefix = i * 2 <= n and nums[:i] == nums[i:2 * i]
            if first_is_prefix:
                answer += n - 2 * i

            # LCP recurrence for positions i and j. The second prefix
            # condition holds when LCP(i,j) >= j-i.
            for j in range(n - 1, i, -1):
                if nums[i] == nums[j]:
                    current[j] = 1 + next_row[j + 1]
                    if current[j] >= j - i and not (first_is_prefix and j >= 2 * i):
                        answer += 1
            next_row = current

        return answer

