import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:1 + n]
    last = {}
    ans = []
    for i, x in enumerate(a, 1):
        ans.append(str(last.get(x, -1)))
        last[x] = i
    sys.stdout.write(' '.join(ans))

if __name__ == '__main__':
    main()

