from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # Each state assigns colors to a symmetric pair (left, right).
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]

        # Process symmetric pairs from the outside toward the center.
        for k in range(1, n // 2):
            left, right = k, n - 1 - k
            next_dp = [10**30] * len(states)
            for old_idx, (a, b) in enumerate(states):
                for new_idx, (x, y) in enumerate(states):
                    # Both neighboring houses on each side must differ.
                    if a != x and b != y:
                        candidate = dp[old_idx] + cost[left][x] + cost[right][y]
                        if candidate < next_dp[new_idx]:
                            next_dp[new_idx] = candidate
            dp = next_dp

        return min(dp)

