        states = [(a,b) for a in range(3) for b in range(3) if a != b]
        m = n // 2
        dp = [cost[0][a] + cost[n-1][b] for a,b in states]
        for k in range(1, m):
            i, j = k, n-1-k
            ndp = [10**30] * 6
            for t, (a,b) in enumerate(states):
                v = dp[t]
                for u, (x,y) in enumerate(states):
                    if a != x and b != y:
                        ndp[u] = min(ndp[u], v + cost[i][x] + cost[j][y])
            dp = ndp
        return min(dp)

