class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = {'a': 1, 'e': 2, 'i': 4, 'o': 8, 'u': 16}
        n = len(word)
        ans = 0
        for left in range(n):
            mask = 0
            consonants = 0
            for right in range(left, n):
                bit = vowels.get(word[right], 0)
                if bit:
                    mask |= bit
                else:
                    consonants += 1
                    if consonants > k:
                        break
                if consonants == k and mask == 31:
                    ans += 1
        return ans

